package com.bank.cddebug;

// A deployable revision. Flags simulate common CD failure causes.
public class Revision {
    private final String tag;
    private final boolean imagePresent;   // false -> ImagePullBackOff
    private final boolean secretPresent;  // false -> CrashLoopBackOff on startup
    private final boolean dbReachable;    // false -> readiness probe never passes

    public Revision(String tag, boolean imagePresent, boolean secretPresent, boolean dbReachable) {
        this.tag = tag;
        this.imagePresent = imagePresent;
        this.secretPresent = secretPresent;
        this.dbReachable = dbReachable;
    }
    public String getTag()        { return tag; }
    public boolean isImagePresent()  { return imagePresent; }
    public boolean isSecretPresent() { return secretPresent; }
    public boolean isDbReachable()   { return dbReachable; }
}
