package com.bank.cddebug;

// Simulated pod: reports a status string like a real kubectl get pods would.
public class Pod {
    private final Revision rev;
    private String status;
    private String lastLog;

    public Pod(Revision rev) { this.rev = rev; }

    // Runs the startup + readiness sequence, setting a status + log.
    public boolean start() {
        if (!rev.isImagePresent()) {
            status = "ImagePullBackOff";
            lastLog = "Failed to pull image " + rev.getTag() + ": not found in registry";
            return false;
        }
        if (!rev.isSecretPresent()) {
            status = "CrashLoopBackOff";
            lastLog = "Startup failed: required secret DB_PASSWORD not found";
            return false;
        }
        if (!rev.isDbReachable()) {
            status = "Running (readiness failing)";
            lastLog = "Health check DOWN: cannot reach database at prod-db:5432";
            return false;
        }
        status = "Running (ready)";
        lastLog = "Started transfer-service " + rev.getTag();
        return true;
    }
    public String getStatus() { return status; }
    public String getLastLog(){ return lastLog; }
}
