package com.bank.cddebug;

import java.util.logging.Logger;

// Reads simulated pod status + logs to classify the CD failure cause.
public class Diagnostics {
    private static final Logger log = Logger.getLogger(Diagnostics.class.getName());

    public String classify(Pod pod) {
        log.info(() -> "kubectl get pods -> status: " + pod.getStatus());
        log.info(() -> "kubectl logs       -> " + pod.getLastLog());
        String status = pod.getStatus();
        if (status.startsWith("ImagePullBackOff")) {
            return "CAUSE: bad image tag or registry credentials";
        } else if (status.startsWith("CrashLoopBackOff")) {
            return "CAUSE: missing secret/config in this environment";
        } else if (status.contains("readiness failing")) {
            return "CAUSE: app up but a dependency (DB) unreachable from this env";
        }
        return "CAUSE: unknown";
    }
}
