package com.bank.cddebug;

import java.util.logging.Logger;

// Attempts a rollout; on failure diagnoses and rolls back to last known good.
public class DeploymentController {
    private static final Logger log = Logger.getLogger(DeploymentController.class.getName());
    private final Diagnostics diagnostics = new Diagnostics();
    private Revision lastKnownGood;

    public DeploymentController(Revision initialGood) {
        this.lastKnownGood = initialGood;
    }

    public boolean deploy(Revision rev) {
        log.info(() -> "CD: rolling out " + rev.getTag());
        Pod pod = new Pod(rev);
        if (pod.start()) {
            log.info(() -> "CD: rollout healthy, " + rev.getTag() + " now serving");
            lastKnownGood = rev; // promote only if healthy
            return true;
        }
        // Failed: diagnose, then roll back safely.
        log.severe("CD: rollout FAILED for " + rev.getTag());
        String cause = diagnostics.classify(pod);
        log.severe(cause);
        log.warning(() -> "Preserving failed pod evidence before rollback");
        rollback();
        return false;
    }

    private void rollback() {
        log.warning(() -> "kubectl rollout undo -> back to last known good "
                + lastKnownGood.getTag());
        Pod good = new Pod(lastKnownGood);
        boolean ok = good.start();
        log.info(() -> "Rollback health check: " + (ok ? "HEALTHY" : "STILL BROKEN - escalate"));
    }
}
