package com.bank.cddebug;

import java.util.logging.*;

public class CdDebugDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CdDebugLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Last known good: everything present and reachable.
        Revision good = new Revision("transfer-service:1.0.0", true, true, true);
        DeploymentController controller = new DeploymentController(good);

        // CI passed, but this revision is missing the DB_PASSWORD secret in prod.
        Revision brokenSecret = new Revision("transfer-service:1.1.0", true, false, true);
        controller.deploy(brokenSecret);  // fails -> diagnose -> rollback

        // A later, correctly-configured revision deploys cleanly.
        Revision fixed = new Revision("transfer-service:1.1.1", true, true, true);
        controller.deploy(fixed);
    }
}

// ─── Would be in CdDebugLogFormatter.java in a real project ───
class CdDebugLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
